/**
 * @summary Reverse a payment (e.g. wrong amount). Creates a reversing Transaction and marks original as reversed.
 */
export const paymentReverse = (
    id: number,
    params?: PaymentReverseParams,
 signal?: AbortSignal
) => {


      return axiosInstance<PaymentDtoResponse>(
      {url: `/api/Payment/${id}/reverse`, method: 'POST',
        params, signal
    },
      );
    }



export const getPaymentReverseMutationOptions = <TError = PaymentDtoResponse,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof paymentReverse>>, TError,{id: number;params?: PaymentReverseParams}, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof paymentReverse>>, TError,{id: number;params?: PaymentReverseParams}, TContext> => {

const mutationKey = ['paymentReverse'];
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof paymentReverse>>, {id: number;params?: PaymentReverseParams}> = (props) => {
          const {id,params} = props ?? {};

          return  paymentReverse(id,params,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type PaymentReverseMutationResult = NonNullable<Awaited<ReturnType<typeof paymentReverse>>>

    export type PaymentReverseMutationError = PaymentDtoResponse

    /**
 * @summary Reverse a payment (e.g. wrong amount). Creates a reversing Transaction and marks original as reversed.
 */
export const usePaymentReverse = <TError = PaymentDtoResponse,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof paymentReverse>>, TError,{id: number;params?: PaymentReverseParams}, TContext>, }
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof paymentReverse>>,
        TError,
        {id: number;params?: PaymentReverseParams},
        TContext
      > => {
      return useMutation(getPaymentReverseMutationOptions(options), queryClient);
    }
    /**
 * @summary Reverse a payment and re-create it for the correct client. Atomic operation for wrong-client corrections.
 */
