    /**
 * @summary Export payments as PDF.
 */
export const paymentGetPdf = (
    params?: PaymentGetPdfParams,
 signal?: AbortSignal
) => {


      return axiosInstance<Blob>(
      {url: `/api/Payment/pdf`, method: 'GET',
        params,
        responseType: 'blob', signal
    },
      );
    }




export const getPaymentGetPdfQueryKey = (params?: PaymentGetPdfParams,) => {
    return [
    `/api/Payment/pdf`, ...(params ? [params] : [])
    ] as const;
    }


export const getPaymentGetPdfQueryOptions = <TData = Awaited<ReturnType<typeof paymentGetPdf>>, TError = unknown>(params?: PaymentGetPdfParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof paymentGetPdf>>, TError, TData>>, }
) => {

const {query: queryOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getPaymentGetPdfQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof paymentGetPdf>>> = ({ signal }) => paymentGetPdf(params, signal);





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof paymentGetPdf>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

